-- would you 
-- 1. change this crystal reports formatted report to ansi joins and formatting (remove double quotes, superlous parenthesis)
-- 2.use existing code base to define field descriptions for PART.USER_8, CUST_ORDER_LINE.USER_2,
--     CUST_ORDER_LINE.USER_6, and CUST_ORDER_LINE.USER_10
--    review KB0731699 and related documentation for field definitions
--    UDF Layout labels and fields are kept in the UDF_LAYOUT table.

SELECT "CUSTOMER_ORDER"."CUSTOMER_ID", "CUST_ORDER_LINE"."PART_ID", "CUSTOMER_ORDER"."STATUS"
, "CUST_ORDER_LINE"."ORDER_QTY", "CUST_ORDER_LINE"."DESIRED_SHIP_DATE", "CUST_ORDER_LINE"."TOTAL_SHIPPED_QTY"
, "PART"."BUYER_USER_ID", "PART"."USER_8", "CUST_ORDER_LINE"."USER_2", "CUST_ORDER_LINE"."USER_6"
, "CUSTOMER_ORDER"."DESIRED_SHIP_DATE", "CUST_ORDER_LINE"."USER_10", "PART"."QTY_AVAILABLE_ISS"
, "CUST_ORDER_LINE"."UNIT_PRICE", "CUSTOMER_ORDER"."ORDER_DATE", "CUSTOMER_ORDER"."CUSTOMER_PO_REF"
, "CUST_ORDER_LINE"."CUST_ORDER_ID", "CUST_ADDRESS"."COUNTRY", "CUST_ADDRESS"."CITY", "CUST_ADDRESS"."STATE"
, "CUST_ORDER_LINE"."MISC_REFERENCE", "PART"."PLANNER_USER_ID", "SKILLS_PART_UDF"."Material_Type"
, "CUST_ADDRESS"."ADDR_NO", "CUST_ADDRESS"."NAME", "CUST_ADDRESS"."ADDR_1", "CUST_ADDRESS"."ADDR_2"
, "CUST_ORDER_LINE"."LINE_NO", "CUST_ORDER_LINE"."LINE_STATUS", "CUST_ORDER_LINE"."CUSTOMER_PART_ID"
, "CUSTOMER_BOOKINGS"."CREATE_DATE", "CUSTOMER_BOOKINGS"."USER_ID", "PART"."PLANNING_LEADTIME"

FROM   (((("Datamart"."dbo"."CUSTOMER_ORDER" "CUSTOMER_ORDER" LEFT OUTER JOIN "Datamart"."dbo"."CUST_ORDER_LINE" "CUST_ORDER_LINE" ON "CUSTOMER_ORDER"."ID"="CUST_ORDER_LINE"."CUST_ORDER_ID") LEFT OUTER JOIN "Datamart"."dbo"."CUST_ADDRESS" "CUST_ADDRESS" ON ("CUSTOMER_ORDER"."CUSTOMER_ID"="CUST_ADDRESS"."CUSTOMER_ID") AND ("CUSTOMER_ORDER"."SHIP_TO_ADDR_NO"="CUST_ADDRESS"."ADDR_NO")) LEFT OUTER JOIN "Datamart"."dbo"."CUSTOMER_BOOKINGS" "CUSTOMER_BOOKINGS" ON "CUSTOMER_ORDER"."ID"="CUSTOMER_BOOKINGS"."CUST_ORDER_ID") LEFT OUTER JOIN "Datamart"."dbo"."PART" "PART" ON "CUST_ORDER_LINE"."PART_ID"="PART"."ID") LEFT OUTER JOIN "Datamart"."dbo"."SKILLS_PART_UDF" "SKILLS_PART_UDF" ON "CUST_ORDER_LINE"."PART_ID"="SKILLS_PART_UDF"."PART_ID"

WHERE  "CUST_ORDER_LINE"."LINE_STATUS"=N'A' AND ("PART"."PLANNER_USER_ID" LIKE N'MFG-MR%' OR "PART"."PLANNER_USER_ID" 
LIKE N'MFG-PL%' OR "PART"."PLANNER_USER_ID" LIKE N'MRP%' OR "PART"."PLANNER_USER_ID" LIKE N'NEW%' OR "PART"."PLANNER_USER_ID" LIKE N'PLAN%') 
AND ("CUSTOMER_ORDER"."STATUS"=N'H' OR "CUSTOMER_ORDER"."STATUS"=N'R')